import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Tab Manager — Glacier","description":"Reorder, relabel, re-icon, hide and redirect sidebar tabs in Glacier — separate lists for general and server pages.","frontmatter":{"title":"Tab Manager — Glacier","description":"Reorder, relabel, re-icon, hide and redirect sidebar tabs in Glacier — separate lists for general and server pages."},"headers":[],"relativePath":"glacier/user-guide/tabs.md","filePath":"glacier/user-guide/tabs.md","lastUpdated":1785230800000}'),s={name:"glacier/user-guide/tabs.md"};function i(n,e,d,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="tab-manager" tabindex="-1">Tab Manager <a class="header-anchor" href="#tab-manager" aria-label="Permalink to &quot;Tab Manager&quot;">​</a></h1><p>Glacier&#39;s sidebar is fully data-driven. The <strong>Tabs</strong> tab in the admin hub edits two independent JSON lists — <code>tabs</code> (general and account pages) and <code>server_tabs</code> (server pages) — through a visual editor. No code, no restarts.</p><h2 id="what-you-can-do-to-any-tab" tabindex="-1">What you can do to any tab <a class="header-anchor" href="#what-you-can-do-to-any-tab" aria-label="Permalink to &quot;What you can do to any tab&quot;">​</a></h2><ul><li><strong>Reorder</strong> — drag tabs into any sequence; category headers follow.</li><li><strong>Relabel</strong> — rename without touching routes (&quot;Databases&quot; → &quot;DB&quot;).</li><li><strong>Re-icon</strong> — swap any tab&#39;s icon from Glacier&#39;s bundled 80+ icon set (all inline SVG, no external assets).</li><li><strong>Hide</strong> — remove a tab from the rail without disabling the underlying page (direct URLs still work).</li><li><strong>Redirect tabs</strong> — add brand-new tabs that link anywhere: an external status page, billing portal, or docs site.</li></ul><h2 id="two-lists-two-contexts" tabindex="-1">Two lists, two contexts <a class="header-anchor" href="#two-lists-two-contexts" aria-label="Permalink to &quot;Two lists, two contexts&quot;">​</a></h2><p><code>tabs</code> governs what users see on the dashboard, account and general pages. <code>server_tabs</code> governs the rail <strong>inside</strong> a server (Console, Files, Databases, Schedules, Users, Backups, Network, Startup, Settings, Activity…). They ship with the stock sets as defaults and diverge only where you edit them.</p><div class="info custom-block"><p class="custom-block-title">Addon tabs are automatic</p><p>Tabs registered by other Blueprint addons (Billing, and friends) are not in either list — Glacier imports them automatically into a collapsible <strong>More</strong> group at the end of the rail, so extensions never become unreachable no matter how you edit the lists.</p></div><h2 id="interaction-polish" tabindex="-1">Interaction polish <a class="header-anchor" href="#interaction-polish" aria-label="Permalink to &quot;Interaction polish&quot;">​</a></h2><ul><li><strong>Active effects</strong> — <code>box</code>, <code>rounded</code>, <code>pill</code>, <code>dot</code> or <code>solid</code> (<code>sidebar_tab_effect</code>), all following the corner-radius setting.</li><li><strong>Hover styles</strong> — <code>soft</code> tint, <code>active</code> (hover previews the exact active effect), or <code>minimal</code> icon-brighten (<code>sidebar_hover_style</code>).</li><li><strong>Jump</strong> — a subtle settle animation when the active tab changes (<code>sidebar_tab_jump</code>).</li><li><strong>Categories</strong> — optional General / Server / Account headers with separators (<code>sidebar_categories</code>, <code>sidebar_separators</code>).</li></ul><h2 id="common-recipes" tabindex="-1">Common recipes <a class="header-anchor" href="#common-recipes" aria-label="Permalink to &quot;Common recipes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>How</th></tr></thead><tbody><tr><td>Cleaner rail for users</td><td>Hide admin-only tabs from <code>tabs</code>; they stay reachable by URL for staff</td></tr><tr><td>Status page in the nav</td><td>Add a redirect tab → your status URL, external-link icon</td></tr><tr><td>Match brand wording</td><td>Relabel stock tabs (&quot;Servers&quot; → &quot;My Servers&quot;)</td></tr><tr><td>Compact server view</td><td>Hide rarely used server tabs from <code>server_tabs</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Hiding ≠ permission</p><p>A hidden tab only removes the link. Pterodactyl&#39;s own permissions still decide who can open the page — use subuser permissions for real access control.</p></div>',12)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
